WITH with_window AS (SELECT a.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM accounts a INNER JOIN subscriptions sub ON a.customer_id = sub.customer_id AND a.opened_date >= sub.start_date AND a.opened_date <= DATE_ADD(sub.end_date, 7)) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, COUNT(DISTINCT customer_id) AS distinct_customer_ids, SUM(CASE WHEN plan = 'premium' THEN balance ELSE 0 END) AS premium_balance, COUNT(DISTINCT id) AS distinct_ids, STDDEV_SAMP(balance) AS balance_stddev, COUNT(DISTINCT plan) AS distinct_plans, APPROX_PERCENTILE(balance, 0.5) AS balance_p50 FROM with_window GROUP BY CUBE (DATE_TRUNC('YEAR', opened_date));
